min_edges = 33

# Create boolean variables for each edge
edges = {}
for i in range(n):
    for j in range(i+1, n):
        edges[(i,j)] = Bool(f"e_{i}_{j}")

solver = Optimize()

# Constraint 1: At least 33 edges
edge_list = [edges[(i,j)] for i in range(n) for j in range(i+1, n)]
solver.add(Sum([If(e, 1, 0) for e in edge_list]) >= min_edges)

# Constraint 2: No triangles (3-cycles)
for i, j, k in itertools.combinations(range(n), 3):
    solver.add(Not(And(edges[(i,j)], edges[(j,k)], edges[(i,k)])))

# Constraint 3: No 4-cycles
# A 4-cycle: i-j-k-l-i where all 4 edges exist
# For each pair of vertices (i,k), they can share at most one common neighbor
for i in range(n):
    for k in range(i+1, n):
        # Common neighbors of i and k
        common = []
        for j in range(n):
            if j != i and j != k:
                if j < i:
                    e1 = edges[(j, i)]
                else:
                    e1 = edges[(i, j)]
                if j < k:
                    e2 = edges[(j, k)]
                else:
                    e2 = edges[(k, j)]
                common.append(And(e1, e2))
        # At most one common neighbor
        for a in range(len(common)):
            for b in range(a+1, len(common)):
                solver.add(Not(And(common[a], common[b])))

