import random
import itertools

n = 30
min_edges = 33

def has_cycle_of_length(edges, length):
    """Check if graph has a cycle of given length."""
    adj = {}
    for u, v in edges:
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)

    # BFS from each vertex to find cycles
    for start in range(n):
        if start not in adj:
            continue
        # BFS with path tracking
        queue = [(start, [start])]
        visited_paths = {start: 0}

        while queue:
            node, path = queue.pop(0)
            if len(path) > length:
                continue
            for neighbor in adj.get(node, set()):
                if neighbor == start and len(path) == length:
                    return True
                if neighbor not in path and len(path) < length:
                    queue.append((neighbor, path + [neighbor]))
    return False

def has_short_cycle(edges, max_length=6):
    """Check if graph has any cycle of length 3 to max_length."""
    adj = {}
    for u, v in edges:
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)

    for length in range(3, max_length + 1):
        if has_cycle_of_length(edges, length):
            return True
    return False

def is_3_colorable(edges):
    """Check if graph is 3-colorable using backtracking."""
    adj = {}
    for u, v in edges:
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)

    color = {}

    def backtrack(v):
        if v == n:
            return True
        for c in range(3):
            valid = True
            for neighbor in adj.get(v, set()):
                if neighbor in color and color[neighbor] == c:
                    valid = False
                    break
            if valid:
                color[v] = c
                if backtrack(v + 1):
                    return True
                del color[v]
        return False

    return backtrack(0)

