    """Find all cycles of given length."""
    adj = {}
    for u, v in edges:
        adj.setdefault(u, set()).add(v)
        adj.setdefault(v, set()).add(u)

    cycles = []
    for start in range(n):
        if start not in adj:
            continue
        # DFS with path tracking
        stack = [(start, [start])]
        while stack:
            node, path = stack.pop()
            if len(path) == length:
                if start in adj.get(node, set()):
                    cycle = tuple(sorted(path))
